at = next(i for i, l in enumerate(lines) if l.startswith('| Step 12a: the credit ledger'))
lines[at + 1:at + 1] = rows
out = nl.join(lines)
out = out.replace('audited, nothing built, left open on purpose', 'audited, left open on purpose at the time (item 598 was built later, see Step 12h)', 1)
open(p, 'w', encoding='utf-8', newline='').write(out)
